// @req REQ-186
// A voiced video, rendered: the voice is muxed into video.mp4 in sync, the
// video keeps the schedule's length, and the spoken word is boxed. The voice
// is a 440 Hz test tone generated by FFmpeg during one word, never a real
// voice. Needs ETHNIAFRICA_VIDEO_ASSETS, like the other acceptance tests.
import { test, after } from "node:test";
import assert from "node:assert/strict";
import { execFileSync } from "node:child_process";
import { createHash } from "node:crypto";
import { mkdtempSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import sharp from "sharp";
import { loadSequence, chapterTimeline } from "./sequence.mjs";
import { renderFrames, encodeVideo } from "./render.mjs";
import { writeVoice, voicedInput } from "./fixtures/voiced.mjs";

const assets = process.env.ETHNIAFRICA_VIDEO_ASSETS;
const options = (extra = {}) => {
  assert.ok(assets, "Set ETHNIAFRICA_VIDEO_ASSETS to the verified imagery");
  return { assets, ...extra };
};
const fixtures = new URL("./fixtures/", import.meta.url);
const work = mkdtempSync(join(tmpdir(), "ethniafrica-voiced-render-"));
after(() => rmSync(work, { recursive: true, force: true }));

// The tone sounds only while « Sahara », chapter 1's first word, is said.
let toneFile = 0;
const tone = (duration, timed) => {
  const { start, end } = timed[1].words[0];
  const file = join(work, `tone-${toneFile++}.wav`);
  execFileSync("ffmpeg", [
    "-v",
    "error",
    "-f",
    "lavfi",
    "-i",
    `aevalsrc='if(between(t,${start},${end}),0.5*sin(2*PI*440*t),0)':s=48000:d=${duration}`,
    "-c:a",
    "pcm_s16le",
    "-fflags",
    "+bitexact",
    "-map_metadata",
    "-1",
    "-y",
    file,
  ]);
  return readFileSync(file);
};
const voice = writeVoice(work, undefined, { audio: tone });
// Flat imagery keeps the render short; the schedule is the same.
const seq = loadSequence(
  voicedInput(voice, (input) => (input.style = "flat")),
  { dir: fixtures }
);
const sahara = voice.timed[1].words[0];
const appear = Math.round(
  chapterTimeline(seq).chapters[0].chunks[0].appear * 30
);

const inkDistance = (rgb, hex) =>
  Math.hypot(
    ...rgb.map((v, i) => v - parseInt(hex.slice(1 + 2 * i, 3 + 2 * i), 16))
  );

// @req REQ-186
test("the voice is muxed in sync into an excerpt that keeps the schedule's length", async () => {
  const range = { from: appear - 15, to: appear + 75 };
  const dir = join(work, "excerpt");
  const { file, manifest } = await encodeVideo(seq, dir, options({ range }));
  const probe = JSON.parse(
    execFileSync("ffprobe", [
      "-v",
      "error",
      "-count_frames",
      "-show_streams",
      "-show_format",
      "-of",
      "json",
      file,
    ])
  );
  const [video] = probe.streams.filter((s) => s.codec_type === "video");
  const [audio] = probe.streams.filter((s) => s.codec_type === "audio");
  assert.equal(Number(video.nb_read_frames), 90);
  assert.equal(audio.codec_name, "aac");
  assert.equal(Number(audio.sample_rate), 48000);
  assert.ok(Math.abs(Number(audio.duration) - 3) < 0.05, audio.duration);
  assert.ok(Math.abs(Number(probe.format.duration) - 3) < 0.05);

  assert.equal(manifest.frames, 90);
  assert.deepEqual(manifest.range, range);
  assert.equal(
    manifest.audio.sha256,
    createHash("sha256").update(readFileSync(voice.audio)).digest("hex")
  );
  assert.ok(Math.abs(manifest.audio.duration - voice.duration) < 1 / 30);

  // The tone sits where « Sahara » is said, relative to the excerpt.
  const pcm = execFileSync(
    "ffmpeg",
    ["-v", "error", "-i", file, "-ac", "1", "-f", "s16le", "-"],
    { maxBuffer: 1 << 26 }
  );
  const samples = new Int16Array(
    pcm.buffer.slice(pcm.byteOffset, pcm.byteOffset + pcm.length)
  );
  const rms = (from, to) => {
    let sum = 0;
    const [a, b] = [Math.round(from * 48000), Math.round(to * 48000)];
    for (let i = a; i < b; i++) sum += samples[i] ** 2;
    return Math.sqrt(sum / (b - a));
  };
  const origin = range.from / 30;
  const [start, end] = [sahara.start - origin, sahara.end - origin];
  assert.ok(rms(start + 0.03, end - 0.03) > 5000, "the tone is in its word");
  assert.ok(rms(0, start - 0.03) < 50, "silence before the word");
  assert.ok(rms(end + 0.03, 2.9) < 50, "silence after the word");
});

// @req REQ-186
test("the same excerpt encodes to the same bytes", async () => {
  const range = { from: appear, to: appear + 6 };
  const [one, two] = [
    await encodeVideo(seq, join(work, "one"), options({ range })),
    await encodeVideo(seq, join(work, "two"), options({ range })),
  ];
  assert.equal(one.manifest.hashes.video, two.manifest.hashes.video);
});

// @req REQ-186
test("the spoken word is boxed in the accent; before its first word the chunk shows no box", async () => {
  // Mid-word, once the chapter's first chunk has faded in.
  const wordFrame = Math.round(((sahara.start + sahara.end) / 2) * 30);
  const [before, during] = await renderFrames(
    seq,
    [Math.ceil(sahara.start * 30) - 1, wordFrame],
    options()
  );
  const accent = async (png) => {
    const { data, info } = await sharp(png)
      .extract({ left: 60, top: 1316, width: 960, height: 136 })
      .raw()
      .toBuffer({ resolveWithObject: true });
    let count = 0;
    for (let i = 0; i < data.length; i += info.channels)
      if (inkDistance([data[i], data[i + 1], data[i + 2]], "#e8b96a") < 12)
        count++;
    return count;
  };
  const [none, lit] = [await accent(before), await accent(during)];
  assert.ok(none < 50, `no box before the first word (${none})`);
  assert.ok(lit > 1500, `a box on « Sahara » (${lit})`);
});

// @req REQ-186
test("an audio file changed after timing is refused at export", async () => {
  const changed = writeVoice(work, undefined, { audio: tone });
  const loaded = loadSequence(voicedInput(changed), { dir: fixtures });
  // Overwrite the audio after loading: its SHA-256 no longer matches.
  writeFileSync(changed.audio, Buffer.alloc(64));
  await assert.rejects(
    encodeVideo(
      loaded,
      join(work, "changed"),
      options({ range: { from: 0, to: 2 } })
    ),
    /SHA-256/
  );
});
